SELECT COUNT(*) FROM att_record
WHERE employee_id = #{employeeId}
  AND place_id = #{placeId}
  AND checkin_type = #{checkinType}
  AND checkin_time >= #{since}

SELECT
FROM att_record r LEFT JOIN hr_employee e ON e.id = r.employee_id LEFT JOIN org_department d ON d.id = e.dept_id LEFT JOIN biz_place p ON p.id = r.place_id
ORDER BY r.checkin_time DESC, r.id DESC LIMIT #{offset}, #{limit}
